<?php if ($notifications): ?><section class="card notice-card"><h2>Kabar terbaru</h2><?php foreach ($notifications as $n): ?><div class="notice-row"><strong><?= e($n->title) ?></strong><span><?= e($n->message) ?></span><small><?= e($n->sent_at) ?></small></div><?php endforeach; ?></section><?php endif; ?>
<form class="search-bar" method="get" action="<?= site_url('petugas') ?>"><input type="search" name="q" value="<?= e($query) ?>" placeholder="Cari nomor, nama, atau instansi"><button class="button primary" type="submit">Cari</button></form>
<div class="card table-card"><div class="table-scroll"><table><thead><tr><th>Nomor</th><th>Pemohon</th><th>Layanan</th><th>Unit</th><th>Status</th><th>Masuk</th><th></th></tr></thead><tbody><?php foreach ($requests as $r): ?><tr><td><strong><?= e($r->request_no) ?></strong></td><td><?= e($r->full_name) ?><small><?= e($r->organization_name) ?></small></td><td><?= $r->service_type === 'tera_ulang' ? 'Tera ulang' : 'Tera' ?></td><td><?= (int) $r->unit_count ?></td><td><span class="badge <?= status_class($r->request_status) ?>"><?= e(status_label($r->request_status)) ?></span></td><td><?= e($r->submitted_at) ?></td><td><a class="table-link" href="<?= site_url('petugas/permohonan/' . $r->id) ?>">Buka →</a></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$requests): ?><div class="empty"><p>Belum ada permohonan yang cocok.</p></div><?php endif; ?></div>
